package greeter

import "strings"

// Slug 把名字转成 URL 友好的 slug：转小写、空白折成单个连字符、首尾不留。
func Slug(name string) string {
	return strings.ToLower(strings.Join(strings.Fields(name), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"spaces become hyphen", "Ada Lovelace", "ada-lovelace"},
		{"case folded", "UPPER Case", "upper-case"},
		{"runs collapsed and trimmed", "  Hello   World  ", "hello-world"},
		{"all whitespace kinds", "Ada\tLovelace\nByron", "ada-lovelace-byron"},
		{"full-width space", "Hello　World", "hello-world"},
		{"unicode case folded", "ÄÖÜ Straße", "äöü-straße"},
		{"empty stays empty", "", ""},
		{"blank stays empty", " \t\n ", ""},
		{"already slug untouched", "already-slug", "already-slug"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}
